insert into public.quiz_templates(key,title,questions) values ('inventions','Идеи, изменившие мир',$catalog$[{"text":"С каким учёным связывают создание периодической системы химических элементов в 1869 году?","options":["Дмитрий Менделеев","Иван Павлов","Сергей Королёв","Николай Лобачевский"],"correct":0,"duration":30,"points":1},{"text":"Кто открыл пенициллин в 1928 году?","options":["Луи Пастер","Александр Флеминг","Чарльз Дарвин","Грегор Мендель"],"correct":1,"duration":30,"points":1},{"text":"Какой учёный сформулировал законы движения и закон всемирного тяготения?","options":["Джеймс Уатт","Майкл Фарадей","Исаак Ньютон","Нильс Бор"],"correct":2,"duration":30,"points":1},{"text":"С чьим именем связывают теорию относительности?","options":["Антуан Лавуазье","Роберт Гук","Карл Линней","Альберт Эйнштейн"],"correct":3,"duration":30,"points":1},{"text":"Кто считается создателем Всемирной паутины World Wide Web?","options":["Тим Бернерс-Ли","Исаак Ньютон","Блез Паскаль","Леонардо да Винчи"],"correct":0,"duration":30,"points":1},{"text":"Какие братья совершили управляемый полёт моторного самолёта в 1903 году?","options":["Братья Гримм","Братья Райт","Братья Люмьер","Братья Коэн"],"correct":1,"duration":30,"points":1},{"text":"Какое изобретение прежде всего связывают с братьями Люмьер?","options":["Радиотелескоп","Компас","Синематограф","Печатную машинку"],"correct":2,"duration":30,"points":1},{"text":"Какой прибор позволяет видеть очень маленькие объекты?","options":["Перископ","Барометр","Спидометр","Микроскоп"],"correct":3,"duration":30,"points":1},{"text":"Какой прибор помогает определять стороны света?","options":["Компас","Секундомер","Микрофон","Манометр"],"correct":0,"duration":30,"points":1},{"text":"Как называется устройство для записи и воспроизведения звука, созданное Эдисоном в 1877 году?","options":["Телеграф","Фонограф","Сейсмограф","Осциллограф"],"correct":1,"duration":30,"points":1},{"text":"Какой учёный проводил опыты с горохом, ставшие основой генетики