insert into public.quiz_templates(key,title,questions) values ('earth','Как устроена Земля',$catalog$[{"text":"Как называется твёрдая внешняя оболочка Земли, включающая кору и верхнюю часть мантии?","options":["Литосфера","Гидросфера","Атмосфера","Ионосфера"],"correct":0,"duration":30,"points":1},{"text":"Как называется водная оболочка Земли?","options":["Литосфера","Гидросфера","Стратосфера","Магнитосфера"],"correct":1,"duration":30,"points":1},{"text":"Как называется газовая оболочка Земли?","options":["Гидросфера","Мантия","Атмосфера","Ядро"],"correct":2,"duration":30,"points":1},{"text":"Как называют расплавленное вещество, вышедшее из вулкана на поверхность?","options":["Магма в глубине","Почва","Лёсс","Лава"],"correct":3,"duration":30,"points":1},{"text":"Как называется прибор для регистрации сейсмических колебаний?","options":["Сейсмограф","Термометр","Гигрометр","Спидометр"],"correct":0,"duration":30,"points":1},{"text":"Как называется точка на поверхности прямо над очагом землетрясения?","options":["Экватор","Эпицентр","Зенит","Полюс"],"correct":1,"duration":30,"points":1},{"text":"Какая из этих горных пород является магматической?","options":["Мел","Мрамор","Базальт","Каменный уголь"],"correct":2,"duration":30,"points":1},{"text":"Как называется линия, делящая Землю на Северное и Южное полушария?","options":["Нулевой меридиан","Северный тропик","Южный полярный круг","Экватор"],"correct":3,"duration":30,"points":1},{"text":"Как называются линии на карте, соединяющие полюса?","options":["Меридианы","Параллели","Изобары","Изотермы"],"correct":0,"duration":30,"points":1},{"text":"Как называются линии, параллельные экватору на глобусе?","options":["Меридианы","Параллели","Русла","Хребты"],"correct":1,"duration":30,"points":1},{"text":"Что вызывает смену дня и ночи?","options":["Обращение Луны вокруг Земли","Изменение расстояния до Солнца каждый час","Вращение Земли вокруг своей оси","Движение облаков"],"correct":2,"duration":30,"points":1},{"text":"Почему на Зе