insert into public.quiz_templates(key,title,questions) values ('logic','Логика за чашкой чая',$catalog$[{"text":"Продолжите ряд: 2, 4, 6, 8, ...","options":["10","9","11","12"],"correct":0,"duration":30,"points":1},{"text":"Продолжите ряд: 1, 2, 4, 8, ...","options":["10","16","12","14"],"correct":1,"duration":30,"points":1},{"text":"Какое число лишнее среди 2, 4, 7, 8, если остальные чётные?","options":["2","4","7","8"],"correct":2,"duration":30,"points":1},{"text":"У трёх велосипедов по два колеса. Сколько колёс всего?","options":["5","8","9","6"],"correct":3,"duration":30,"points":1},{"text":"В корзине 5 яблок. Два достали. Сколько осталось в корзине?","options":["3","2","5","7"],"correct":0,"duration":30,"points":1},{"text":"На двух руках человека 10 пальцев. Сколько пальцев на четырёх таких руках?","options":["15","20","25","40"],"correct":1,"duration":30,"points":1},{"text":"Если сегодня среда, какой день будет послезавтра?","options":["Четверг","Суббота","Пятница","Вторник"],"correct":2,"duration":30,"points":1},{"text":"Если все лисы — млекопитающие, а Рыжик — лиса, кто Рыжик?","options":["Птица","Насекомое","Рыба","Млекопитающее"],"correct":3,"duration":30,"points":1},{"text":"Что тяжелее: 1 кг железа или 1 кг ваты?","options":["Они весят одинаково","Железо","Вата","Зависит от цвета ваты"],"correct":0,"duration":30,"points":1},{"text":"Книга стоит 100 рублей. После скидки 20 рублей сколько она стоит?","options":["20 рублей","80 рублей","90 рублей","120 рублей"],"correct":1,"duration":30,"points":1},{"text":"Какой месяц идёт сразу после апреля?","options":["Март","Июнь","Май","Февраль"],"correct":2,"duration":30,"points":1},{"text":"В комнате четыре угла. В каждом сидит одна кошка. Сколько кошек в комнате?","options":["8","12","16","4"],"correct":3,"duration":30,"points":1},{"text":"Три друга пожали друг другу руки по одному разу. Сколько рукопожатий было?","options":["3","2","6","9"],"correct":0,"duration":30,"points":1},{"text":"Сколько раз нужно разрезать