insert into public.quiz_templates(key,title,questions) values ('culture','Традиции мира',$catalog$[{"text":"В какой стране зародилось искусство складывания бумаги оригами?","options":["Япония","Мексика","Норвегия","Бразилия"],"correct":0,"duration":30,"points":1},{"text":"Как называется традиционная японская одежда с широкими рукавами?","options":["Сари","Кимоно","Пончо","Килт"],"correct":1,"duration":30,"points":1},{"text":"С какой страной прежде всего ассоциируется традиционная одежда сари?","options":["Шотландия","Мексика","Индия","Исландия"],"correct":2,"duration":30,"points":1},{"text":"Как называется традиционная клетчатая одежда, связанная с Шотландией?","options":["Кимоно","Тога","Сари","Килт"],"correct":3,"duration":30,"points":1},{"text":"С какой страной прежде всего связывают танец фламенко?","options":["Испания","Япония","Канада","Швеция"],"correct":0,"duration":30,"points":1},{"text":"Какой танец исторически связан с Аргентиной и Уругваем?","options":["Полька","Танго","Фламенко","Краковяк"],"correct":1,"duration":30,"points":1},{"text":"В какой стране проходит знаменитый карнавал в Рио-де-Жанейро?","options":["Португалия","Испания","Бразилия","Чили"],"correct":2,"duration":30,"points":1},{"text":"В какой стране традиционно отмечают День мёртвых с праздничными алтарями?","options":["Финляндия","Монголия","Кения","Мексика"],"correct":3,"duration":30,"points":1},{"text":"Какой праздник обычно ассоциируют с украшенной ёлкой в России?","options":["Новый год","День знаний","Масленица","День космонавтики"],"correct":0,"duration":30,"points":1},{"text":"Какое блюдо особенно ассоциируется с Масленицей?","options":["Суши","Блины","Лазанья","Ризотто"],"correct":1,"duration":30,"points":1},{"text":"Как называют традиционную русскую деревянную игрушку из вложенных друг в друга фигурок?","options":["Неваляшка из одного корпуса","Свистулька","Матрёшка","Кубик Рубика"],"correct":2,"duration":30,"points":1},{"text":"Какое дерево изображено листом на флаге Канады?","options":["Дуб","Берёза","Кипарис","Клён"],"correct":3,"duration":30,"points":1},{"text":"Какой цветок часто служит символом Нидерландов?","options":["Тюльпан","Лотос","Эдельвейс","Гибискус"],"correct":0,"duration":30,"points":1},{"text":"Какое животное изображено на гербе Австралии вместе с эму?","options":["Панда","Кенгуру","Белый медведь","Лев"],"correct":1,"duration":30,"points":1},{"text":"Какая традиционная японская процедура связана с приготовлением и подачей матча?","options":["Оригами","Икебана","Чайная церемония","Каллиграфия"],"correct":2,"duration":30,"points":1}]$catalog$::jsonb) on conflict(key) do update set title=excluded.title,questions=excluded.questions;
